def gen(rng):
    tests = ['3 5', '2 1', '5 3', '1 1', '1 6', '2 2', '2 3', '4 4', '3 3', '1000000000 1']
    for m in range(1, 6):
        for n in range(1, 8):
            if m ** n <= 6000:
                tests.append(f"{m} {n}")
    for _ in range(10):
        m = rng.randint(1, 6)
        n = rng.randint(1, 8)
        while m ** n > 6000:
            n -= 1
        tests.append(f"{m} {n}")
    N = 2 * 10**5
    tests += [f"1 {N}", f"3 {N}", f"{N} {N}", f"1000000000 {N}", f"{rng.randint(2, 5000)} {N}", f"{N - 1} {N}"]
    return tests
